// --- Settings, machines, updates (Phase 7; owned by @/screens/settings + machines)

type SettingsSectionRoute =
  | "general"
  | "appearance"
  | "experiments"
  | "usage"
  | "updates";

/** One settings bucket (`/settings/<section>`; the web paths too). */
export function settingsSectionHref(section: SettingsSectionRoute): Href {
  return untypedHref(`/settings/${section}`);
}


/** The machines list (`/settings/machines`). */
export function machinesHref(): Href {
  return untypedHref("/settings/machines");
}

/** One machine (`/settings/machines/[hostId]`; the web path too). */
export function machineDetailHref(hostId: string): Href {
  return untypedHref("/settings/machines/[hostId]", { hostId });
}
